import{z as f,x as B,o as s,c as A,q as l,j as E,D as i,d as t,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const j=JSON.parse('{"title":"jiffies","description":"","frontmatter":{"title":"jiffies","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jiffies.md","filePath":"cs/jiffies.md","lastUpdated":1791413859000}'),p={name:"cs/jiffies.md"};function d(m,e,D,h,C,c){const r=B("Mermaid");return s(),A("div",null,[e[2]||(e[2]=l('<h1 id="jiffies" tabindex="-1">jiffies <a class="header-anchor" href="#jiffies" aria-label="Permalink to &quot;jiffies&quot;">​</a></h1><div class="epigraph"><p>内核用滴答中断累加一个计数器；HZ 次每秒，超时、调度记账和时间片都曾以它为粗粒度时钟。</p><footer>—— 据 Bovet and Cesati；Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/io-uring">上一课</a>的等待可以带超时，却还没有「内核如何数时间」。<a href="/cs/timeslice-cfs">时间片</a> 已用时间记账，当时把时钟当黑盒。<a href="/cs/interrupt-bottom-half">中断下半部</a> 假定定时器 IRQ 会来。缺口是 <strong>jiffies</strong>：滴答、HZ、回绕、以及它不够精细——留给下一课 hrtimer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次睡眠都读 CPU 周期计数器，旧机器没有或不同核会漂。经典 Unix：编程间隔定时器，HZ（如 100 或 250）次每秒加一。超时时刻记成「未来的 jiffies」。缺口：谁在 IRQ 里加一、32 位回绕如何比较、用户 <code>sleep</code> 的分辨率不能高于滴答。动态 HZ 与无滴答（tickless）是实现，对象仍是「软件时间基」。</p><p><span class="marginnote">数字实例：HZ=100 时每秒滴答 100 次、每次 10ms，「睡 1 秒」就是把目标 jiffies 设成当前值加 100；若 HZ=250，粒度变 4ms，同一秒要数 250 滴。</span></p><p>本课不把每架构的时钟事件设备编程写完。</p><p><span class="marginnote">比较用有符号差处理回绕。jiffies 不是 UTC；墙上时钟是另一套（xtime），可被 NTP 调。本课只钉单调滴答。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>时钟 IRQ → 更新 jiffies → 检查定时器轮（timer wheel）上到期的软件定时器 → 可能标记调度。进程在内核睡眠时把「目标 jiffies」挂进等待队列。超时与 <a href="/cs/select-poll">select</a> 共用这条。不要把 TSC 校准全文展开；jiffies 可以由更高精度时钟累加出来。</p>',10)),(s(),E(o,null,{default:i(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E6%BB%B4%E7%AD%94%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20INC%5B%22jiffies%2B%2B%22%5D%0A%20%20INC%20--%3E%20WHEEL%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E8%BD%AE%E5%88%B0%E6%9C%9F%22%5D%0A%20%20WHEEL%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%E7%9D%A1%E7%9C%A0%E8%80%85%20%2F%20%E8%AE%B0%E8%B4%A6%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"jiffies 把时间变成整数，让 OS 能在没有用户态时钟的情况下做公平调度与 I/O 超时。分辨率与延迟下限被 HZ 绑住：HZ=100 则 10ms 粒度。这解释了为何管道超时与 nanosleep 在旧内核上不准。下一课用时钟事件设备实现更高分辨率，而不必把 HZ 拉到十万。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：有符号差比较像跨午夜算工时——23:50 干到 00:05，直接相减得负数，但取「最近的方向」理解就是 15 分钟；jiffies 回绕时用 \\((\\mathrm{long})(later - earlier)\\) 同理得到正确的小正数。")],-1)),e[6]||(e[6]=a("p",null,"计数器回绕时如何仍判断「到期没有」：",-1)),(s(),E(o,null,{default:i(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOW%5B%22now%20%3D%204294967290%EF%BC%8C%E9%80%BC%E8%BF%91%2032%20%E4%BD%8D%E9%A1%B6%22%5D%20--%3E%20ADD%5B%22%E7%9B%AE%E6%A0%87%20%3D%20now%20%2B%2010%22%5D%0A%20%20ADD%20--%3E%20WRAP%5B%22%E5%87%A0%E6%8B%8D%E5%90%8E%E8%AE%A1%E6%95%B0%E5%9B%9E%E7%BB%95%E5%88%B0%200%20%E9%99%84%E8%BF%91%22%5D%0A%20%20WRAP%20--%3E%20DIFF%5B%22%E6%9C%89%E7%AC%A6%E5%8F%B7%E5%B7%AE%20(long)(now%20-%20%E7%9B%AE%E6%A0%87)%22%5D%0A%20%20DIFF%20--%3E%7C%22%E5%B7%AE%E4%B8%BA%E6%AD%A3%22%7C%20EXP%5B%22%E5%B7%B2%E5%88%B0%E6%9C%9F%EF%BC%8C%E5%94%A4%E9%86%92%22%5D%0A%20%20DIFF%20--%3E%7C%22%E5%B7%AE%E4%B8%BA%E8%B4%9F%22%7C%20WAIT%5B%22%E6%9C%AA%E5%88%B0%E6%9C%9F%EF%BC%8C%E7%BB%A7%E7%BB%AD%E7%9D%A1%22%5D%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p>与组成课的时钟域不同：这里是软件计数，不是 PLL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CLOCK_MONOTONIC 的全部 POSIX 钟。不保证虚拟机里滴答与真时间 1:1（偷时间）。下一课：纳秒级期限与红黑树定时器。</p><p><span class="marginnote">常见误区：初学者容易拿 jiffies 当墙上时钟。它是单调递增的计数，不理会 NTP、不对应任何日期；显示「现在几点」要读另一套可被调整的时钟。</span></p><p>后课默认：粗超时可用 jiffies。细期限与高精度时钟事件，下一课 hrtimer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>jiffies 由滴答累加，驱动 timer wheel 与记账。</li><li>分辨率受 HZ 限制，回绕用有符号差比较。</li><li>高精度定时是 hrtimer 的缺口。</li><li>出处：Bovet and Cesati, <em>ULK</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const T=f(p,[["render",d]]);export{j as __pageData,T as default};
